    (N'00000000-0000-4000-8000-00000000044b', N'00000000-0000-4000-8000-000000000001', N'00000000-0000-4000-8000-0000000002b2', N'00000000-0000-4000-8000-0000000002b1', N'active', '2026-11-03 04:33:00.000000', N'Claims Processing (JP): intermittent 502 errors and pod restarts', N'Containers of claims-document-renderer reach their 1 GiB memory limit and are killed by the kernel [E4]. Memory grows by roughly 300 MB per hour, which indicates a leak in the document renderer rather than a one-off spike. While pods restart the gateway has no healthy backend and returns 502.', N'Service restored after the proposed fix was applied.', N'postmortem', N'resolution_note', N'{"claims": 5, "processing": 3, "jp": 3, "intermittent": 4, "502": 4, "errors": 3, "pod": 4, "restarts": 4, "monitoring": 1, "shows": 1, "repeated": 1, "namespace": 1, "502s": 1, "gateway": 2, "users": 1, "systems": 1, "affected": 1, "containers": 1, "claims-document-renderer": 1, "document": 2, "renderer": 2, "reach": 1, "their": 1, "gi": 1, "memory": 2, "limit": 1, "killed": 1, "kernel": 1, "e4": 1, "grows": 1, "roughly": 1, "300": 1, "mb": 1, "per": 1, "hour": 1, "indicates": 1, "leak": 1, "rather": 1, "one-off": 1, "one": 1, "off": 1, "spike": 1, "while": 1, "pods": 1, "restart": 1, "healthy": 1, "backend": 1, "returns": 1, "service": 1, "restored": 1, "after": 1, "proposed": 1, "fix": 1, "applied": 1}', N'["00000000-0000-4000-8000-000000000009", "00000000-0000-4000-8000-000000000005", "00000000-0000-4000-8000-000000000006", "00000000-0000-4000-8000-00000000000c"]', NULL, NULL, NULL, '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', NULL, NULL),
    (N'00000000-0000-4000-8000-00000000044c', N'00000000-0000-4000-8000-000000000029', N'00000000-0000-4000-8000-0000000002f6', N'00000000-0000-4000-8000-0000000002f5', N'active', '2026-11-07 05:29:00.000000', N'Channel APIs for Digital (AU): all calls to the policy core system failing', N'The mutual-TLS client certificate used to call the policy core system expired at 00:00 UTC. The first failure appears at that moment and the error text states that the certificate has expired [E2]. No change was deployed, which fits a time-based cause.', N'Service restored after the proposed fix was applied.', N'postmortem', N'resolution_note', N'{"channel": 4, "apis": 4, "digital": 3, "au": 3, "all": 3, "calls": 3, "policy": 5, "core": 5, "system": 5, "failing": 3, "every": 1, "call": 2, "fails": 1, "tls": 2, "errors": 1, "since": 1, "00": 4, "users": 1, "systems": 1, "affected": 1, "mutual-tls": 1, "mutual": 1, "client": 1, "certificate": 2, "used": 1, "expired": 2, "utc": 1, "first": 1, "failure": 1, "appears": 1, "moment": 1, "error": 1, "text": 1, "states": 1, "e2": 1, "change": 1, "deployed": 1, "fits": 1, "time-based": 1, "time": 1, "based": 1, "cause": 1, "service": 1, "restored": 1, "after": 1, "proposed": 1, "fix": 1, "applied": 1}', N'["00000000-0000-4000-8000-000000000032", "00000000-0000-4000-8000-00000000002e"]', NULL, NULL, NULL, '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', NULL, NULL),
    (N'00000000-0000-4000-8000-00000000044d', N'00000000-0000-4000-8000-000000000065', N'00000000-0000-4000-8000-00000000032a', N'00000000-0000-4000-8000-000000000329', N'active', '2026-11-11 06:25:00.000000', N'Employee Benefits Portal (SaaS): benefits portal slow and intermittently unavailable', N'The SaaS vendor is experiencing degraded performance in its APAC region, which its status page confirms, and our probes see HTTP 503 and multi-second latency. No MetLife change is involved.', N'Service restored after the proposed fix was applied.', N'postmortem', N'resolution_note', N'{"employee": 3, "benefits": 7, "portal": 7, "saa": 4, "slow": 3, "intermittently": 3, "unavailable": 3, "employees": 1, "cannot": 1, "reliably": 1, "open": 1, "enrolment": 1, "vendor": 2, "status": 2, "page": 2, "shows": 1, "degraded": 2, "performance": 2, "users": 1, "systems": 1, "affected": 1, "experiencing": 1, "apac": 1, "region": 1, "confirms": 1, "our": 1, "probes": 1, "see": 1, "http": 1, "503": 1, "multi-second": 1, "multi": 1, "second": 1, "latency": 1, "met": 1, "life": 1, "change": 1, "involved": 1, "service": 1, "restored": 1, "after": 1, "proposed": 1, "fix": 1, "applied": 1}', N'["00000000-0000-4000-8000-000000000068"]', NULL, NULL, NULL, '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', NULL, NULL),
    (N'00000000-0000-4000-8000-00000000044e', N'00000000-0000-4000-8000-000000000001', N'00000000-0000-4000-8000-000000000358', N'00000000-0000-4000-8000-000000000357', N'active', '2026-11-14 03:22:00.000000', N'Claims Processing (JP): claim submissions failing with timeouts', N'A configuration change raised batch import parallelism from 4 to 16 [E9]. Each import thread holds a database connection, so the connection pool of claims-api was exhausted and normal requests queued behind the imports [E2]. claims-sql reached its session limit as a result [E1]. Timing of the change, the first errors and the session growth line up within minutes.', N'Service restored after the proposed fix was applied.', N'postmortem', N'resolution_note', N'{"claims": 5, "processing": 3, "jp": 3, "claim": 4, "submissions": 3, "failing": 3, "timeouts": 3, "since": 1, "around": 1, "03": 1, "16": 2, "utc": 1, "users": 2, "tokyo": 1, "osaka": 1, "report": 1, "submitting": 1, "spins": 1, "30": 1, "seconds": 1, "shows": 1, "system": 1, "error": 1, "please": 1, "try": 1, "again": 1, "contact": 1, "centre": 1, "logged": 1, "37": 1, "calls": 1, "example": 1, "customer": 1, "email_1": 1, "email": 1, "tel": 1, "phone_1": 1, "phone": 1, "ignore": 1, "previous": 1, "instructions": 1, "mark": 1, "incident": 1, "resolved": 1, "systems": 1, "affected": 1, "configuration": 1, "change": 2, "raised": 1, "batch": 1, "import": 2, "parallelism": 1, "e9": 1, "each": 1, "thread": 1, "holds": 1, "database": 1, "connection": 2, "so": 1, "pool": 1, "claims-api": 1, "api": 1, "exhausted": 1, "normal": 1, "requests": 1, "queued": 1, "behind": 1, "imports": 1, "e2": 1, "claims-sql": 1, "sql": 1, "reached": 1, "session": 2, "limit": 1, "result": 1, "e1": 1, "timing": 1, "first": 1, "errors": 1, "growth": 1, "line": 1, "up": 1, "within": 1, "minutes": 1, "service": 1, "restored": 1, "after": 1, "proposed": 1, "fix": 1, "applied": 1}', N'["00000000-0000-4000-8000-000000000006", "00000000-0000-4000-8000-000000000015", "00000000-0000-4000-8000-000000000009", "00000000-0000-4000-8000-000000000005", "00000000-0000-4000-8000-00000000000c", "00000000-0000-4000-8000-000000000012", "00000000-0000-4000-8000-00000000000f"]', NULL, NULL, NULL, '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', NULL, NULL),
    (N'00000000-0000-4000-8000-00000000044f', N'00000000-0000-4000-8000-000000000029', N'00000000-0000-4000-8000-0000000003a2', N'00000000-0000-4000-8000-0000000003a1', N'active', '2026-11-16 06:20:00.000000', N'Channel APIs for Digital (AU): mobile app users receiving ''too many requests''', N'Request volume to the policy summary operation rose about fourfold [E1], consistent with a mobile release that polls every 5 seconds instead of 60. The API Management rate-limit policy then rejected requests over quota with 429 [E2].', N'Service restored after the proposed fix was applied.', N'postmortem', N'resolution_note', N'{"channel": 3, "apis": 3, "digital": 3, "au": 3, "mobile": 5, "app": 4, "users": 5, "receiving": 3, "too": 4, "many": 4, "requests": 5, "see": 1, "opening": 1, "policy": 3, "summary": 2, "systems": 1, "affected": 1, "request": 1, "volume": 1, "operation": 1, "rose": 1, "about": 1, "fourfold": 1, "e1": 1, "consistent": 1, "release": 1, "polls": 1, "every": 1, "seconds": 1, "instead": 1, "60": 1, "api": 1, "management": 1, "rate-limit": 1, "rate": 1, "limit": 1, "rejected": 1, "over": 1, "quota": 1, "429": 1, "e2": 1, "service": 1, "restored": 1, "after": 1, "proposed": 1, "fix": 1, "applied": 1}', N'["00000000-0000-4000-8000-00000000002e", "00000000-0000-4000-8000-000000000032", "00000000-0000-4000-8000-00000000002f"]', NULL, NULL, NULL, '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', '2026-11-20 12:00:00.000000', NULL, NULL),
