    (N'00000000-0000-4000-8000-0000000002d8', N'00000000-0000-4000-8000-0000000002b2', N'application', N'A memory leak in the document renderer', N'Memory in the document renderer grows steadily until the container limit is reached, which points at unreleased buffers in the application. This is the underlying defect. [E4]', N'1. Memory climbs steadily across the window rather than spiking [E4]. 2. A leak explains why restarts help only temporarily. The code location is not identified in the knowledge base.', 0.55, N'["E4"]', N'[]', N'{"schema_version": 2, "summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"step_id": "application-1", "title": "Re-check this lens", "purpose": "diagnose", "risk_level": "low", "risk_reasons": ["model:low", "computed:low"], "warnings": [], "assumptions": [], "has_assumed_values": false, "missing_value_count": 0, "action": {"action_kind": "manual_action", "description": "Re-check this lens if the leading hypothesis is disproved.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}, "check": null, "revert": null}], "code_changes": []}', N'low', NULL, 0, N'inconclusive', N'inconclusive', NULL, N'The evidence neither supports nor rules out this lens.', 0, '2026-11-20 12:00:00.000000'),
