    (N'00000000-0000-4000-8000-000000000384', N'00000000-0000-4000-8000-000000000358', N'application', N'Release raised batch import parallelism and exhausted the SQL connection pool', N'A configuration change shortly before onset raised parallel batch imports from 4 to 16 threads. claims-api then ran out of pooled SQL connections and began timing out. [E9] [E2]', N'1. Errors on claims-api are connection acquisition timeouts, a pattern new compared with the baseline [E2]. 2. A configuration change preceded onset by minutes [E9]. 3. claims-sql session usage rose in step with the errors [E1]. The change explains both the new pattern and the timing.', 0.86, N'["E2", "E9", "E1"]', N'[]', N'{"schema_version": 2, "summary": "Restore the previous batch import concurrency, restart the service to release saturated connections, then cap parallelism below the pool size.", "steps": [{"step_id": "application-1", "title": "Restore the previous batch import concurrency", "purpose": "mitigate", "risk_level": "medium", "risk_reasons": ["model:medium", "computed:medium"], "warnings": ["restarts_service", "contains_assumptions"], "assumptions": [], "has_assumed_values": true, "missing_value_count": 0, "action": {"action_kind": "configuration_change", "description": "Set BATCH_IMPORT_PARALLELISM back to 4 on claims-api (it is 16 now).", "expected_result": "", "risk_level": "medium", "command": null, "configuration_change": {"target_kind": "kubernetes_environment_variable", "service_name": "claims-api", "service_in_catalogue": true, "setting_name": {"name": "setting", "value_kind": "configuration_key", "value": "BATCH_IMPORT_PARALLELISM", "value_source": "evidence", "source_code": "E9", "status": "verified", "status_reason": null}, "before_value": {"name": "before", "value_kind": "configuration_value", "value": "16", "value_source": "evidence", "source_code": "E9", "status": "verified", "status_reason": null}, "after_value": {"name": "after", "value_kind": "configuration_value", "value"