    (N'00000000-0000-4000-8000-000000000385', N'00000000-0000-4000-8000-000000000358', N'dependencies', N'Azure SQL reached its session limit', N'claims-sql hit its session and request limit, so claims-api could not obtain connections. The database is the place where the failure surfaces, but the evidence points to the caller creating the load. [E1] [E7]', N'1. claims-sql shows elevated sessions [E1] and errors [E4]. 2. However the session growth starts after the configuration change [E9], which makes the database a victim rather than the origin. Confidence is moderate because the saturation itself is real.', 0.52, N'["E1", "E4", "E9"]', N'[]', N'{"schema_version": 2, "summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"step_id": "dependencies-1", "title": "Re-check this lens", "purpose": "diagnose", "risk_level": "low", "risk_reasons": ["model:low", "computed:low"], "warnings": [], "assumptions": [], "has_assumed_values": false, "missing_value_count": 0, "action": {"action_kind": "manual_action", "description": "Re-check this lens if the leading hypothesis is disproved.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}, "check": null, "revert": null}], "code_changes": []}', N'low', NULL, 0, N'inconclusive', N'inconclusive', NULL, N'The evidence neither supports nor rules out this lens.', 1, '2026-11-20 12:00:00.000000'),
