    (N'00000000-0000-4000-8000-0000000003c1', N'00000000-0000-4000-8000-0000000003a2', N'application', N'A mobile release polls the policy summary every 5 seconds', N'A new mobile app release polls the policy summary every 5 seconds instead of 60, multiplying request volume and tripping the gateway rate limit. [E3] [E1]', N'1. Request volume on one operation rose about fourfold [E1]. 2. Throttling messages name the subscription and operation [E2]. 3. The increase matches a client polling change, not organic growth.', 0.68, N'["E1", "E2"]', N'[]', N'{"schema_version": 2, "summary": "Raise the rate limit temporarily to stop user-facing 429 responses, then restore the 60 second polling interval in the mobile app.", "steps": [{"step_id": "application-1", "title": "Raise the rate limit temporarily", "purpose": "mitigate", "risk_level": "medium", "risk_reasons": ["model:medium", "computed:low"], "warnings": [], "assumptions": [], "has_assumed_values": false, "missing_value_count": 0, "action": {"action_kind": "manual_action", "description": "Raise the per-subscription limit in the inbound policy of the mobile policy-summary operation (change process applies).", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}, "check": {"action_kind": "rerun_evidence_query", "description": "429 responses drop.", "expected_result": "Below 1 percent.", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": "E3", "withheld_reason": null}, "revert": {"action_kind": "manual_action", "description": "Restore the previous policy revision of the API in API Management.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}}, {"step_id": "application-2", "title": "Ship the mobile hot-fix", "purpose": "durable_fix", "risk_level": "low", "risk_reasons": ["model:low", "computed:low"], "warnings": [],