    (N'00000000-0000-4000-8000-0000000003c3', N'00000000-0000-4000-8000-0000000003a2', N'infrastructure', N'API Management rate-limit policy is too low for current traffic', N'The API Management rate-limit policy returns 429 once a subscription exceeds its quota, and the quota is now too low for the new traffic pattern. [E2]', N'1. The rate-limit policy is working as configured [E2]. 2. Gateway capacity rose to 1.6x but did not saturate [E1]. The policy value is a contributing condition, the load change is the trigger.', 0.62, N'["E2", "E1"]', N'[]', N'{"schema_version": 2, "summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"step_id": "infrastructure-1", "title": "Re-check this lens", "purpose": "diagnose", "risk_level": "low", "risk_reasons": ["model:low", "computed:low"], "warnings": [], "assumptions": [], "has_assumed_values": false, "missing_value_count": 0, "action": {"action_kind": "manual_action", "description": "Re-check this lens if the leading hypothesis is disproved.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}, "check": null, "revert": null}], "code_changes": []}', N'low', NULL, 0, N'inconclusive', N'inconclusive', NULL, N'The evidence neither supports nor rules out this lens.', 2, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-0000000003fe', N'00000000-0000-4000-8000-0000000003df', N'application', N'Retries without jitter amplify the partner slowdown', N'The payment client retries five times without jitter, multiplying the load on a slow partner and exhausting its own outbound HTTP pool. This worsens the incident but is not its trigger. [E3]', N'1. Retry attempts 1 to 5 appear in the logs [E3]. 2. Retries without jitter amplify an external slowdown, but the slowdown existed first [E7].', 0.45, N'["E3", "E7"]', N'[]', N'{"schema_version": 2, "summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"step_id": "application-1", "title": "Re-check this lens", "purpose": "diagnose", "risk_level": "low", "risk_reasons": ["model:low", "computed:low"], "warnings": [], "assumptions": [], "has_assumed_values": false, "missing_value_count": 0, "action": {"action_kind": "manual_action", "description": "Re-check this lens if the leading hypothesis is disproved.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}, "check": null, "revert": null}], "code_changes": []}', N'low', NULL, 0, N'inconclusive', N'inconclusive', NULL, N'The evidence neither supports nor rules out this lens.', 0, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-0000000003ff', N'00000000-0000-4000-8000-0000000003df', N'dependencies', N'The partner payment gateway is responding in more than 25 seconds', N'The partner bank gateway is timing out calls to its confirm endpoint (more than 25 seconds). Every payment confirmation that depends on it is delayed. [E7] [E3]', N'1. Calls to the partner endpoint time out after 25 s [E3]. 2. Dependency failures are new compared with the baseline [E7]. 3. Latency increased several-fold only on operations that call the partner.', 0.84, N'["E3", "E7"]', N'[]', N'{"schema_version": 2, "summary": "Stop amplifying the partner slowdown: enable the circuit-breaker fallback, add jitter to retries and engage the partner.", "steps": [{"step_id": "dependencies-1", "title": "Check the partner endpoint latency", "purpose": "diagnose", "risk_level": "low", "risk_reasons": ["model:low", "computed:low"], "warnings": [], "assumptions": [], "has_assumed_values": false, "missing_value_count": 0, "action": {"action_kind": "rerun_evidence_query", "description": "Check the partner endpoint latency from a trusted host (read-only).", "expected_result": "Latency is back below the timeout.", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": "E3", "withheld_reason": null}, "check": null, "revert": null}, {"step_id": "dependencies-2", "title": "Enable the circuit-breaker fallback", "purpose": "mitigate", "risk_level": "medium", "risk_reasons": ["model:medium", "computed:low"], "warnings": [], "assumptions": [], "has_assumed_values": false, "missing_value_count": 0, "action": {"action_kind": "manual_action", "description": "Enable the payment gateway circuit-breaker fallback so confirmations are queued instead of retried synchronously.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}, "check": {"action_kind": "rerun_evidence_query", "description": "Outbound HTTP client pool usage falls.", "expected_result": "Pool usage below 70 percent.", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": "E3", "withheld_reason": null}, "revert": {"action_kind": "manual_action", "description": "Disable the fallback queue once the partner is healthy and drain deferred confirmations.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}}, {"step_id": "dependencies-3", "title": "Engage the partner", "purpose": "mitigate", "risk_level": "low", "risk_reasons": ["model:low", "computed:low"], "warnings": ["no_validation"], "assumptions": [], "has_assumed_values": false, "missing_value_count": 0, "action": {"action_kind": "manual_action", "description": "Raise the incident with the partner bank''s operations contact and share the timeout timestamps from the evidence.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}, "check": null, "revert": null}], "code_changes": [{"repository_name": "payment-confirmation-func", "file_path": "file not identified", "change_description": "Use exponential back-off with jitter and a total retry budget instead of five immediate retries.", "before_snippet": "Policy.Handle<TaskCanceledException>().WaitAndRetryAsync(5, _ => TimeSpan.FromSeconds(1))", "after_snippet": "Policy.Handle<TaskCanceledException>().WaitAndRetryAsync(Backoff.DecorrelatedJitterBackoffV2(TimeSpan.FromSeconds(2), 3))"}]}', N'medium', N'00000000-0000-4000-8000-0000000000a3', 1, N'supported', N'supported', NULL, N'Direct evidence that changed against the baseline fits the onset [E3] [E7].', 1, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-000000000400', N'00000000-0000-4000-8000-0000000003df', N'infrastructure', N'Network or compute limits on the payments platform', N'Platform metrics are in range; nothing suggests the payments platform itself is constrained. [E15]', N'1. CPU, memory and restart counters are normal [E15]. 2. Latency is confined to calls toward the partner.', 0.12, N'[]', N'["E15"]', N'{"schema_version": 2, "summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"step_id": "infrastructure-1", "title": "Re-check this lens", "purpose": "diagnose", "risk_level": "low", "risk_reasons": ["model:low", "computed:low"], "warnings": [], "assumptions": [], "has_assumed_values": false, "missing_value_count": 0, "action": {"action_kind": "manual_action", "description": "Re-check this lens if the leading hypothesis is disproved.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}, "check": null, "revert": null}], "code_changes": []}', N'low', NULL, 0, N'ruled_out', N'ruled_out', NULL, N'A source that was read shows nothing abnormal for this lens [E15].', 2, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-00000000042e', N'00000000-0000-4000-8000-00000000041c', N'application', N'PBIL0400 abended S0C7 on a malformed packed-decimal premium amount', N'Job PBIL0400 ended with ABEND S0C7 (data exception) in program PBILCALC while processing a premium amount that is not valid packed decimal. [E1]', N'1. IEF450I and $HASP395 both report ABEND=S0C7 for step STEP030 [E1]. 2. S0C7 means arithmetic on invalid packed decimal data. 3. CEE3207S names program PBILCALC.', 0.85, N'["E1"]', N'[]', N'{"schema_version": 2, "summary": "Correct or skip the malformed input record, then restart the job from the failed step as the runbook describes.", "steps": [{"step_id": "application-1", "title": "Find the malformed record", "purpose": "diagnose", "risk_level": "low", "risk_reasons": ["model:low", "computed:low"], "warnings": [], "assumptions": [], "has_assumed_values": false, "missing_value_count": 0, "action": {"action_kind": "manual_action", "description": "Identify the malformed packed-decimal premium amount in PBIL.INPUT.D1119 from the dump of step STEP030.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}, "check": null, "revert": null}, {"step_id": "application-2", "title": "Correct the input record", "purpose": "mitigate", "risk_level": "medium", "risk_reasons": ["model:medium", "computed:low"], "warnings": [], "assumptions": [], "has_assumed_values": false, "missing_value_count": 0, "action": {"action_kind": "manual_action", "description": "Correct or remove the record in a copy of the input data set (data change, requires batch operations approval).", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}, "check": {"action_kind": "manual_action", "description": "Compare the copy with the original to see only that record changed.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}, "revert": {"action_kind": "manual_action", "description": "Keep the original input data set untouched so the run can be repeated.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}}, {"step_id": "application-3", "title": "Restart the job from the failed step", "purpose": "mitigate", "risk_level": "medium", "risk_reasons": ["model:medium", "computed:low"], "warnings": [], "assumptions": [], "has_assumed_values": false, "missing_value_count": 0, "action": {"action_kind": "manual_action", "description": "Restart PBIL0400 from STEP030 with RESTART=STEP030 on the job card, through the batch scheduler.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}, "check": {"action_kind": "manual_action", "description": "PBIL0400 ends with condition code 0000 and downstream statements are produced.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}, "revert": {"action_kind": "manual_action", "description": "Nothing to undo: a failed run can be repeated from the same step.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}}], "code_changes": []}', N'medium', N'00000000-0000-4000-8000-0000000000a4', 1, N'supported', N'supported', NULL, N'Direct evidence that changed against the baseline fits the onset [E1].', 0, '2026-11-20 12:00:00.000000'),
    (N'00000000-0000-4000-8000-00000000042f', N'00000000-0000-4000-8000-00000000041c', N'dependencies', N'A late or corrupt input feed', N'The malformed record probably originates upstream, so an input feed is a contributing factor. The abend itself is data-driven. [E1]', N'1. A bad value in the input data set had to come from the upstream extract. 2. No evidence shows the feed was late.', 0.3, N'[]', N'[]', N'{"schema_version": 2, "summary": "No change is recommended from this perspective until the leading hypothesis is ruled out.", "steps": [{"step_id": "dependencies-1", "title": "Re-check this lens", "purpose": "diagnose", "risk_level": "low", "risk_reasons": ["model:low", "computed:low"], "warnings": [], "assumptions": [], "has_assumed_values": false, "missing_value_count": 0, "action": {"action_kind": "manual_action", "description": "Re-check this lens if the leading hypothesis is disproved.", "expected_result": "", "risk_level": "low", "command": null, "configuration_change": null, "evidence_code": null, "withheld_reason": null}, "check": null, "revert": null}], "code_changes": []}', N'low', NULL, 0, N'inconclusive', N'inconclusive', NULL, N'The evidence neither supports nor rules out this lens.', 1, '2026-11-20 12:00:00.000000'),
