 with the 502s.", "confidence_score": 0.82, "assessment": "supported", "assessment_reason_markdown": "Direct evidence that changed against the baseline fits the onset [E4].", "supporting_evidence_codes": ["E4"], "contradicting_evidence_codes": [], "proposed_fix": {"summary": "Relieve memory pressure with a temporary limit increase and restart; fix the renderer''s unreleased image buffers.", "steps": [{"title": "Confirm which pods are close to the limit", "purpose": "diagnose", "action": {"action_kind": "command", "description": "Confirm which pods are close to the limit (read-only).", "command": {"tool": "kubectl", "dialect": "any", "template": "kubectl top pods -n {{namespace}}", "parameters": [{"name": "namespace", "value_kind": "kubernetes_namespace", "value": "claims-docs", "value_source": "service_catalogue", "source_code": null}]}, "configuration_change": null, "evidence_code": null, "expected_result": ""}, "check": null, "revert": null, "risk_level": "low", "assumptions": []}, {"title": "Temporarily raise the memory limit", "purpose": "mitigate", "action": {"action_kind": "command", "description": "Temporarily raise the memory limit of claims-document-renderer to 2Gi.", "command": {"tool": "kubectl", "dialect": "any", "template": "kubectl set resources deployment/{{name}} -n {{namespace}} --limits=memory=2Gi", "parameters": [{"name": "name", "value_kind": "kubernetes_name", "value": "claims-document-renderer", "value_source": "service_catalogue", "source_code": null}, {"name": "namespace", "value_kind": "kubernetes_namespace", "value": "claims-docs", "value_source": "service_catalogue", "source_code": null}]}, "configuration_change": null, "evidence_code": null, "expected_result": ""}, "check": {"action_kind": "manual_action", "description": "No new OOMKilled restarts.", "command": null, "configuration_change": null, "evidence_code": null, "expected_result": "No new restarts for 30 minutes."}, "revert": {"action_kind": "command", "description": "Return to the previous revision, with its old limit.", "command": {"tool": "kubectl", "dialect": "any", "template": "kubectl rollout undo deployment/{{name}} -n {{namespace}}", "parameters": [{"name": "name", "value_kind": "kubernetes_name", "value": "claims-document-renderer", "value_source": "service_catalogue", "source_code": null}, {"name": "namespace", "value_kind": "kubernetes_namespace", "value": "claims-docs", "value_source": "service_catalogue", "source_code": null}]}, "configuration_change": null, "evidence_code": null, "expected_result": ""}, "risk_level": "medium", "assumptions": []}, {"title": "Restart the deployment", "purpose": "mitigate", "action": {"action_kind": "command", "description": "Restart the deployment to clear leaked memory.", "command": {"tool": "kubectl", "dialect": "any", "template": "kubectl rollout restart deployment/{{name}} -n {{namespace}}", "parameters": [{"name": "name", "value_kind": "kubernetes_name", "value": "claims-document-renderer", "value_source": "service_catalogue", "source_code": null}, {"name": "namespace", "value_kind": "kubernetes_namespace", "value": "claims-docs", "value_source": "service_catalogue", "source_code": null}]}, "configuration_change": null, "evidence_code": null, "expected_result": ""}, "check": {"action_kind": "manual_action", "description": "No new OOMKilled restarts.", "command": null, "configuration_change": null, "evidence_code": null, "expected_result": "No new restarts for 30 minutes."}, "revert": {"action_kind": "manual_action", "description": "Nothing to undo: new pods start from the current revision.", "command": null, "configuration_change": null, "evidence_code": null, "expected_result": ""}, "risk_level": "medium", "assumptions": []}, {"title": "Release image buffers", "purpose": "durable_fix", "action": {"action_kind": "manual_action", "description": "Release image buffers after each render and add a memory-based alert at 80 percent of the limit.", "command": null, "configuration_change": null, "evidence_code": null, "expected_result": ""}, "check": {"action_kind": "manual_action", "description": "Confirm memory stays flat across a day of rendering.", "command": null, "configuration_change": null, "evidence_code": null, "expected_result": ""}, "revert": null, "risk_level": "low", "assumptions": []}], "code_changes": [{"repository_name": "claims-document-renderer", "file_path": "file not identified (document renderer image pipeline)", "change_description": "Dispose image buffers after each render.", "before_snippet": "var bitmap = Render(document);\nreturn bitmap.ToPng();", "after_snippet": "using var bitmap = Render(document);\nreturn bitmap.ToPng();"}]}, "fix_risk_level": "medium", "matched_runbook_code": "R1"}', 5174, 0, N'c8272fbe3c3df85cffe4c7c487b60f2183d7adeb74162b59367ed772ac92c433', N'[{"code": "file_path_replaced", "parameters": {"count": 1}}]', NULL, N'00000000-0000-4000-8000-0000000002da', NULL),
