e the partner.", "steps": [{"title": "Check the partner endpoint latency", "purpose": "diagnose", "action": {"action_kind": "rerun_evidence_query", "description": "Check the partner endpoint latency from a trusted host (read-only).", "command": null, "configuration_change": null, "evidence_code": "E3", "expected_result": "Latency is back below the timeout."}, "check": null, "revert": null, "risk_level": "low", "assumptions": []}, {"title": "Enable the circuit-breaker fallback", "purpose": "mitigate", "action": {"action_kind": "manual_action", "description": "Enable the payment gateway circuit-breaker fallback so confirmations are queued instead of retried synchronously.", "command": null, "configuration_change": null, "evidence_code": null, "expected_result": ""}, "check": {"action_kind": "rerun_evidence_query", "description": "Outbound HTTP client pool usage falls.", "command": null, "configuration_change": null, "evidence_code": "E3", "expected_result": "Pool usage below 70 percent."}, "revert": {"action_kind": "manual_action", "description": "Disable the fallback queue once the partner is healthy and drain deferred confirmations.", "command": null, "configuration_change": null, "evidence_code": null, "expected_result": ""}, "risk_level": "medium", "assumptions": []}, {"title": "Engage the partner", "purpose": "mitigate", "action": {"action_kind": "manual_action", "description": "Raise the incident with the partner bank''s operations contact and share the timeout timestamps from the evidence.", "command": null, "configuration_change": null, "evidence_code": null, "expected_result": ""}, "check": null, "revert": null, "risk_level": "low", "assumptions": []}], "code_changes": [{"repository_name": "payment-confirmation-func", "file_path": "file not identified (PaymentGatewayClient retry policy)", "change_description": "Use exponential back-off with jitter and a total retry budget instead of five immediate retries.", "before_snippet": "Policy.Handle<TaskCanceledException>().WaitAndRetryAsync(5, _ => TimeSpan.FromSeconds(1))", "after_snippet": "Policy.Handle<TaskCanceledException>().WaitAndRetryAsync(Backoff.DecorrelatedJitterBackoffV2(TimeSpan.FromSeconds(2), 3))"}]}, "fix_risk_level": "medium", "matched_runbook_code": "R1"}', 3148, 0, N'52964b594cd68caf4183c130636f20076d4c9645923bb484918891b45121c72e', N'[{"code": "file_path_replaced", "parameters": {"count": 1}}]', NULL, N'00000000-0000-4000-8000-0000000003ff', NULL),
