INSERT INTO [keigan].[incident_memory_key] ([incident_memory_entry_id], [key_kind], [key_value_hash], [key_display_text])
SELECT [source].[incident_memory_entry_id], [source].[key_kind], [source].[key_value_hash], [source].[key_display_text] FROM #demo_rows AS [source]
WHERE NOT EXISTS (SELECT 1 FROM [keigan].[incident_memory_key] AS [existing] WHERE [existing].[incident_memory_entry_id] = [source].[incident_memory_entry_id] AND [existing].[key_kind] = [source].[key_kind] AND [existing].[key_value_hash] = [source].[key_value_hash]);
DROP TABLE #demo_rows;
GO
